import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;
    static final int DIM = 32;
    static final int MAX_D = 64;
    static final int MAX_K = 32;

    static class Matrix {
        int[][] data = new int[DIM][DIM];

        Matrix() {
            for (int i = 0; i < DIM; i++) {
                for (int j = 0; j < DIM; j++) {
                    data[i][j] = 0;
                }
            }
        }

        int[] getRow(int i) {
            return data[i];
        }

        static Matrix multiply(Matrix A, Matrix B) {
            Matrix R = new Matrix();
            for (int i = 0; i < DIM; i++) {
                for (int j = 0; j < DIM; j++) {
                    for (int k = 0; k < DIM; k++) {
                        R.data[i][j] = addMod(R.data[i][j], multiplyMod(A.data[i][k], B.data[k][j]));
                    }
                }
            }
            return R;
        }
    }

    static int addMod(int a, int b) {
        int res = a + b;
        if (res >= MOD) res -= MOD;
        return res;
    }

    static int multiplyMod(int a, int b) {
        return (int)((long)a * b % MOD);
    }

    static Matrix createMatrix(int n, int offset, int k, Matrix[] f) {
        Matrix M = new Matrix();
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                int ni = (i == k) ? i : (i + offset) % k;
                int nj = (j == k) ? j : (j + offset) % k;
                M.data[ni][nj] = f[n].data[i][j];
            }
        }
        return M;
    }

    static int computeDigitSum(long n, int k) {
        int sum = 0;
        while (n > 0) {
            sum += n % k;
            n /= k;
        }
        return sum % k;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int base = sc.nextInt();
        int k = base;

        int digits = 0;
        long tmp = n;
        while (tmp > 0) {
            tmp /= k;
            digits++;
        }

        Matrix[] f = new Matrix[MAX_D];
        for (int i = 0; i < MAX_D; i++) {
            f[i] = new Matrix();
        }

        // Initialize identity matrix
        Matrix identity = new Matrix();
        for (int i = 0; i <= k; i++) {
            identity.data[i][i] = 1;
        }

        // Initialize f[0]
        f[0] = identity;
        for (int i = 0; i <= k; i++) {
            f[0].data[i][0] = 1;
        }

        // Build f for each digit position
        for (int i = 1; i < digits; i++) {
            f[i] = identity;
            for (int j = 0; j < k; j++) {
                f[i] = Matrix.multiply(f[i], createMatrix(i - 1, j, k, f));
            }
        }

        long current = 0;
        long power = 1;

        // Decrease digits by 1 for processing
        digits--;
        for (int i = 0; i < digits; i++) {
            power *= k;
        }

        Matrix result = new Matrix();
        // Initialize result as identity
        for (int i = 0; i <= k; i++) {
            result.data[i][i] = 1;
        }

        while (current < n) {
            // Ensure digits >= 0
            if (digits < 0) break;
            while (current + power <= n) {
                int digitSum = computeDigitSum(current, k);
                result = Matrix.multiply(result, createMatrix(digits, digitSum, k, f));
                current += power;
            }
            power /= k;
            digits--;
        }

        int total = 0;
        for (int i = 0; i <= k; i++) {
            total = addMod(total, result.data[k][i]);
        }
        System.out.println(total);
        sc.close();
    }
}
